import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(instance, properties):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': instance, 'properties': properties}))['returnValue'])

def setv(instance, values):
    ok = execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': instance, 'values': json.dumps(values)}))['returnValue']
    if not ok: raise RuntimeError('set properties failed: ' + str(instance))

def compile_bp(path):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': load(path), 'warnings_as_errors': True}))

def save(paths):
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('save failed')

def run():
    paths = []
    ability_path = '/ExtractionOps/AbilitySystem/AbilitySet_ExtractionCore'
    setv(load(ability_path), {'grantedAttributes': [{'attributeSet': {'refPath': '/Script/ExtractionOpsRuntime.ExtractionArmorSet'}}]})
    pawn_path = '/ExtractionOps/Pawns/DA_ExtractionPawnData'
    pawn = load(pawn_path)
    ability_sets = get(pawn, ['abilitySets'])['abilitySets']
    if not any('AbilitySet_ExtractionCore' in str(x) for x in ability_sets):
        ability_sets.append({'refPath': ability_path + '.' + ability_path.split('/')[-1]})
        setv(pawn, {'abilitySets': ability_sets})
    paths += [ability_path, pawn_path]

    component_action = {'refPath': '/ExtractionOps/ExtractionOps.ExtractionOps:GameFeatureAction_AddComponents_0'}
    components = get(component_action, ['componentList'])['componentList']
    additions = [
      {'actorClass': {'refPath':'/Script/LyraGame.LyraPlayerState'}, 'componentClass': {'refPath':'/Script/ExtractionOpsRuntime.ExtractionInventoryComponent'}, 'bClientComponent': True, 'bServerComponent': True, 'additionFlags': 0},
      {'actorClass': {'refPath':'/Script/LyraGame.LyraPlayerState'}, 'componentClass': {'refPath':'/Script/ExtractionOpsRuntime.ExtractionRaidLifecycleComponent'}, 'bClientComponent': True, 'bServerComponent': True, 'additionFlags': 0},
      {'actorClass': {'refPath':'/Script/LyraGame.LyraGameState'}, 'componentClass': {'refPath':'/Script/ExtractionOpsRuntime.ExtractionThreatDirectorComponent'}, 'bClientComponent': False, 'bServerComponent': True, 'additionFlags': 0}
    ]
    for addition in additions:
        if not any(str(x.get('componentClass','')).find(addition['componentClass']['refPath'].split('.')[-1]) >= 0 for x in components):
            components.append(addition)
    setv(component_action, {'componentList': components})
    paths.append('/ExtractionOps/ExtractionOps')

    for path in ['/ExtractionOps/Weapons/Rifle/GE_Damage_ExtractionRifle','/ExtractionOps/Weapons/Shotgun/GE_Damage_ExtractionShotgun']:
        effect = load(path)
        executions = get(effect, ['executions'])['executions']
        if not executions: raise RuntimeError('damage effect has no execution: ' + path)
        executions[0]['calculationClass'] = {'refPath': '/Script/ExtractionOpsRuntime.ExtractionDamageExecution'}
        setv(effect, {'executions': executions})
        paths.append(path)

    configs = {
      'DA_Ammo_Rifle': ('Ammo','Common',0,30,True,None),
      'DA_Ammo_Shells': ('Ammo','Common',0,16,True,None),
      'DA_Item_Medkit': ('Consumable','Common',150,2,True,'/Game/GameplayEffects/Heal/GE_Heal_Instant.GE_Heal_Instant_C'),
      'DA_Valuable_ScrapMetal': ('Valuable','Common',100,4,True,None),
      'DA_Valuable_PowerCell': ('Valuable','Common',125,4,True,None),
      'DA_Valuable_CircuitBoard': ('Valuable','Common',150,4,True,None),
      'DA_Valuable_OpticModule': ('Valuable','Uncommon',300,2,True,None),
      'DA_Valuable_ServoMotor': ('Valuable','Uncommon',350,2,True,None),
      'DA_Valuable_EncryptedDrive': ('Valuable','Uncommon',450,2,True,None),
      'DA_Valuable_ReactorCore': ('Valuable','Rare',900,1,True,None),
      'DA_Valuable_PrototypeChip': ('Valuable','Rare',1200,1,True,None)
    }
    for name, cfg in configs.items():
        category,tier,value,stack,droppable,effect = cfg
        values = {'definitionId': name, 'displayName': name.replace('DA_','').replace('_',' '), 'category': category, 'tier': tier, 'baseValue': value, 'maxStackSize': stack, 'bDroppable': droppable}
        if effect: values['useGameplayEffect'] = {'refPath': effect}
        path = '/ExtractionOps/Items/' + name
        setv(load(path), values)
        paths.append(path)

    for path in ['/ExtractionOps/World/Loot/B_ExtractionWorldPickup','/ExtractionOps/World/Loot/B_ExtractionLootContainer']:
        compile_bp(path)
        paths.append(path)
    save(paths)
    return {'configured': paths, 'componentCount': len(components)}
